contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "not enough test balance");

        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(address(this), amount, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            reverted
                ? (afterC == beforeC && afterDeposits == beforeDeposits)
                : (afterSelf >= beforeSelf && afterC <= beforeC && beforeDeposits == afterDeposits)
        );
    }
}

